<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { useRouter } from 'vue-router'; import { useProfileStore } from '../stores/profile'; import { platforms,platformById,normalizeUrl } from '../platforms'; import type { PlatformType,ProfileGoal } from '../types'; import ProfilePreview from '../components/ProfilePreview.vue'; import ImageCropper from '../components/ImageCropper.vue'
const store=useProfileStore(),router=useRouter(),step=ref(1),selected=ref<PlatformType[]>([]),links=ref<Record<string,string>>({}),cropSrc=ref(''),email=ref(''),sent=ref(false),error=ref(''),origin=window.location.origin; const total=6
onMounted(()=>store.restore()); const recommended=computed(()=>platforms.filter(p=>p.goals.includes(store.profile.goal))); function toggle(id:PlatformType){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
function next(){error.value='';if(step.value===2&&!selected.value.length){error.value='Choose at least one platform.';return}if(step.value===3){for(const id of selected.value){const v=links.value[id];if(v&&!normalizeUrl(v)){error.value=`Enter a valid ${platformById(id).name} link.`;return}}store.profile.links=[];selected.value.forEach(id=>store.addLink(id,platformById(id).name,normalizeUrl(links.value[id]||'')))}step.value=Math.min(total,step.value+1);void store.save()}
function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>cropSrc.value=String(r.result);r.readAsDataURL(f)}
async function authenticate(){if(!email.value.includes('@')){error.value='Enter a valid email address.';return}try{const r=await store.requestMagicLink(email.value);if(r.demo){await store.publish();router.push('/dashboard')}else sent.value=true}catch(e:any){error.value=e.message}}
</script>
<template><div class="onboarding"><header><a class="wordmark" href="/">✳ <b>LinkCard</b></a><div class="progress"><i :style="{width:`${step/total*100}%`}"></i></div><span>{{step}} / {{total}}</span></header><main>
  <button v-if="step>1" class="back" @click="step--">← Back</button>
  <section v-if="step===1"><div class="intro"><small>LET'S GET STARTED</small><h1>What brings you here?</h1><p>We’ll personalize your links and starter design.</p></div><div class="goal-grid"><button v-for="g in ([['creator','Creator','Build an audience and share your work.','✦'],['business','Business','Reach customers and grow your brand.','◆'],['personal','Personal','Keep everything about you in one place.','●']] as const)" :key="g[0]" :class="{selected:store.profile.goal===g[0]}" @click="store.profile.goal=g[0] as ProfileGoal"><i>{{g[3]}}</i><div><b>{{g[1]}}</b><span>{{g[2]}}</span></div></button></div></section>
  <section v-else-if="step===2"><div class="intro"><small>YOUR LINKS</small><h1>Where can people find you?</h1><p>Select every platform you want on your profile.</p></div><div class="platform-grid"><button v-for="p in recommended" :key="p.id" :class="{selected:selected.includes(p.id)}" @click="toggle(p.id)"><i :style="{background:p.color}">{{p.icon}}</i><b>{{p.name}}</b><span>✓</span></button></div></section>
  <section v-else-if="step===3"><div class="intro"><small>ADD CONTENT</small><h1>Paste your links</h1><p>Use the full link to each page. You can change these later.</p></div><div class="link-form"><label v-for="id in selected" :key="id"><i :style="{background:platformById(id).color}">{{platformById(id).icon}}</i><div><span>{{platformById(id).name}}</span><input v-model="links[id]" type="url" :placeholder="platformById(id).placeholder"></div></label></div></section>
  <section v-else-if="step===4"><div class="intro"><small>MAKE IT YOURS</small><h1>Introduce yourself</h1><p>Add a clear photo and a short, useful introduction.</p></div><div class="identity-card"><label class="photo-upload"><img v-if="store.profile.imageUrl" :src="store.profile.imageUrl"><span v-else>＋</span><input type="file" accept="image/png,image/jpeg,image/webp" @change="upload"><b>{{store.profile.imageUrl?'Change photo':'Upload photo'}}</b></label><div class="identity-fields"><label>Display name<input v-model="store.profile.displayName" maxlength="50"></label><label>Title or description<input v-model="store.profile.title" maxlength="80"></label><label>Bio<textarea v-model="store.profile.bio" maxlength="240"></textarea><small>{{store.profile.bio.length}} / 240</small></label><label>Image description<input v-model="store.profile.imageAlt" placeholder="Describe the photo for screen readers"></label></div></div></section>
  <section v-else-if="step===5" class="theme-step"><div><div class="intro left"><small>YOUR STYLE</small><h1>Choose a starting look</h1><p>Fine-tune every detail in the editor.</p></div><div class="theme-options"><button v-for="t in [{n:'Electric',a:'#7137ff',b:'#18152b',x:'#caff39'},{n:'Sunset',a:'#ff6a3d',b:'#35122c',x:'#ffd93d'},{n:'Clean',a:'#f4f1ea',b:'#d8f44a',x:'#111111'},{n:'Midnight',a:'#121827',b:'#243a5e',x:'#6ee7ff'}]" :key="t.n" @click="Object.assign(store.profile.theme,{background:t.b,backgroundEnd:t.a,accent:t.x,textColor:t.n==='Clean'?'#111':'#fff',buttonColor:t.n==='Clean'?'#111':'#fff',buttonTextColor:t.n==='Clean'?'#fff':'#111'})"><i :style="{background:`linear-gradient(135deg,${t.b},${t.a})`}"></i><b>{{t.n}}</b></button></div></div><div class="phone-frame"><ProfilePreview :profile="store.profile" /></div></section>
  <section v-else><div class="intro"><small>READY TO PUBLISH</small><h1>Claim your profile</h1><p>We’ll email you a secure sign-in link. No password needed.</p></div><div v-if="!sent" class="publish-form"><label>Public address<div><span>{{origin}}/u/</span><input v-model="store.profile.slug" pattern="[a-z0-9-]+" @input="store.profile.slug=store.profile.slug.toLowerCase().replace(/[^a-z0-9-]/g,'')"></div></label><label>Email address<input v-model="email" type="email" placeholder="you@example.com"></label><button class="primary-action" @click="authenticate">Publish my profile →</button><small v-if="!store.backendEnabled">Demo mode: profile will publish locally until Supabase is configured.</small></div><div v-else class="sent-card"><i>✉</i><h2>Check your inbox</h2><p>Use the magic link sent to {{email}} to finish publishing.</p></div></section>
  <p v-if="error" class="form-error">{{error}}</p><button v-if="step<total" class="continue" @click="next">Continue <span>→</span></button>
  <ImageCropper v-if="cropSrc" :src="cropSrc" @cancel="cropSrc=''" @done="v=>{store.profile.imageUrl=v;cropSrc=''}" />
</main></div></template>
